// Generated by scripts/build-academy-data.mjs from the Season 1 production sources. Do not edit by hand.
export const ACADEMY_CONTENT = Object.freeze({"locale":"id","lessons":[{"ep":1,"title":"Harga satu bitcoin mahal. Apakah saya masih bisa beli sedikit?","goal":"Membedakan jumlah koin dari nominal uang yang dibelanjakan, serta memahami bahwa bitcoin bisa dibeli dalam pecahan desimal.","task":"Di panel latihan, ubah nominal belanja 100 menjadi jumlah koin. Tidak ada pesanan riil yang dibuat.","answer":"0.002 BTC (biaya belum dipotong).","takeaways":["Harga satu bitcoin utuh bukanlah modal minimum untuk mulai.","Bitcoin bisa dibagi menjadi pecahan desimal: belanjakan 100 USDT di harga 50.000 dan kamu memiliki 0,002 BTC.","Setiap platform menetapkan minimum order dan biayanya sendiri, jadi periksa keduanya dulu."],"quiz":{"q":"Satu bitcoin seharga 50.000 USDT. Kamu membelanjakan 100 USDT, belum termasuk biaya. Berapa BTC yang kamu dapat?","options":["Tidak ada, kamu butuh satu koin utuh","0,002 BTC","0,02 BTC"],"answer":1,"why":"100 ÷ 50.000 = 0,002. Kamu bisa memiliki sebagian dari satu bitcoin."},"transcript":[{"t":0.25,"who":"sam","text":"Satu koin semahal itu? Uang saya bahkan nggak cukup buat tiket masuk."},{"t":9.25,"who":"nexubo","text":"Itu harga satu koin utuh, bukan nominal yang wajib dibayar setiap kali beli. Bitcoin adalah aset digital, bisa dimiliki dalam pecahan desimal. Biasanya tidak perlu beli satu koin utuh."},{"t":25.25,"who":"narrator","text":"Contoh soal latihan: Andaikan satu bitcoin seharga 50,000 USDT dan kamu beli 100. Tanpa menghitung biaya, itu 0.002 bitcoin. Ini bukan harga pasar hari ini."},{"t":45.25,"who":"sam","text":"Lalu bagaimana saat harganya bergerak?"},{"t":47,"who":"nexubo","text":"Jumlah koinmu tetap sama, tapi nilainya bisa naik dan turun. Beli sedikit berarti risikonya lebih kecil, bukan tanpa risiko sama sekali."},{"t":62.25,"who":"nexubo","text":"Bisa dipecah, tapi tidak semua platform menerima order terlalu kecil. Periksa nominal minimum dan biayanya. Saat belajar, pakai dana virtual saja. Tidak perlu deposit."},{"t":75.25,"who":"narrator","text":"Apakah harus beli satu bitcoin utuh? Tidak. Ingat: harga satu koin bukanlah modal awal untuk mulai."},{"t":86.25,"who":"narrator","text":"Sebagian besar transaksi dihargai dalam USDT. Tapi apakah USDT benar-benar satu dolar? Episode berikutnya."},{"t":92.55,"who":"narrator","text":"Pahami dulu, baru bertindak."}]},{"ep":2,"title":"Apakah USDT itu dolar? Mengapa sering muncul saat beli kripto?","goal":"Memahami fungsi stablecoin, target patokan, serta risikonya, dan tahu bahwa beli kripto tidak harus lewat USDT dulu.","task":"Kelompokkan 'deposito bank dolar', 'USDT', dan 'BTC' ke dalam kategori yang tepat.","answer":"USDT adalah stablecoin, sejenis aset kripto. Ini bukan simpanan bank dalam bentuk dolar.","takeaways":["USDT adalah stablecoin yang dirancang agar tetap dekat dengan satu dolar, bukan simpanan bank.","Bursa memakainya untuk memberi harga dan menukar aset, jadi penjualan sering berakhir dalam USDT.","\"Stabil\" adalah tujuan desain: harganya bisa bergeser dan penukarannya punya syarat."],"quiz":{"q":"Pernyataan mana tentang USDT yang benar?","options":["Itu adalah dolar di rekening bank Anda","Itu adalah stablecoin, salah satu jenis aset kripto","Nilainya tidak pernah bisa menjauh dari satu dolar"],"answer":1,"why":"USDT berusaha mengikuti dolar, tetapi tetap aset kripto dengan risiko penerbit dan platformnya sendiri."},"transcript":[{"t":0.25,"who":"sam","text":"Namanya Tether, jadi intinya ini saldo dolar di bank, kan?"},{"t":9.25,"who":"nexubo","text":"Bukan. USDT, atau Tether, adalah stablecoin. Tujuannya menjaga nilai mendekati satu dolar, tapi ini bukan saldo bank dan bukan uang tunai bebas risiko."},{"t":25.25,"who":"narrator","text":"Bursa sering memakainya untuk patokan harga dan swap. Kamu bisa beli bitcoin dengan USDT, dan saat menjual, kamu mungkin menerima USDT, bukan transfer bank."},{"t":45.25,"who":"nexubo","text":"'Stabil' adalah target desain, bukan jaminan pasti. Harganya bisa bergeser, serta penerbitan dan penebusan memiliki syarat. Pahami risiko penerbit dan platform."},{"t":62.25,"who":"sam","text":"Jadi saya harus beli USDT dulu sebelum beli bitcoin?"},{"t":65.23,"who":"nexubo","text":"Tidak selalu. Mata uang dan pasangan perdagangan yang tersedia bergantung pada wilayah dan platformmu."},{"t":75.25,"who":"narrator","text":"Apa yang salah dari kalimat ini? Stablecoin bukan jaminan uang aman. Pahami fungsinya, dan ketahui bahwa nilainya bisa tidak stabil."},{"t":86.25,"who":"narrator","text":"Jika ponselmu rusak malam ini, apakah koinmu juga hilang? Berikutnya: di mana koinmu sebenarnya berada."},{"t":92.15,"who":"narrator","text":"Pahami dulu, baru bertindak."}]},{"ep":3,"title":"Di mana koin saya? Bursa vs dompet","goal":"Membedakan akun bursa kustodial dengan dompet mandiri (self-custody), serta memahami kontrol akses dan pemulihan.","task":"Cocokkan dua skenario: akun login bursa dan dompet mandiri standar dengan recovery phrase.","answer":"Keduanya berbeda dalam pihak yang memegang kendali dan cara pemulihannya. Self-custody bukan berarti otomatis aman.","takeaways":["Di akun bursa, platformlah yang terutama mengelola aset dan kuncinya.","Di dompet kustodi mandiri, Anda yang mengendalikan kredensial, dan tanggung jawab pemulihan ada pada Anda.","Sebelum memilih, tanyakan siapa yang memegang izin untuk memindahkan aset."],"quiz":{"q":"Anda kehilangan frasa pemulihan dompet kustodi mandiri standar dan tidak punya cara pemulihan lain. Apa yang terjadi?","options":["Tim dukungan bisa meresetnya untuk Anda","Akses bisa hilang selamanya","Bursa memulihkannya secara otomatis"],"answer":1,"why":"Dengan kustodi mandiri, Anda yang memegang kunci. Tanpa frasa atau cara sah lainnya, tidak ada yang bisa memulihkannya untuk Anda."},"transcript":[{"t":0.25,"who":"sam","text":"Ponsel saya rusak. Apakah koin saya ikut hilang?"},{"t":9.25,"who":"nexubo","text":"Koinmu tidak disimpan di dalam ponsel. Dompet membantumu melihat aset di blockchain dan memakai kunci untuk otorisasi. Bisa pulih atau tidak tergantung jenis dompet dan cadangan yang kamu simpan."},{"t":32.25,"who":"narrator","text":"Dengan akun kustodial bursa, platform mengelola aset dan kunci, kamu bertindak lewat akun. Dengan dompet mandiri, kamu memegang kredensial. Kemudahan dan tanggung jawab terbagi berbeda."},{"t":60.25,"who":"sam","text":"Kalau lupa kata sandi di salah satunya, tinggal hubungi CS saja?"},{"t":63.86,"who":"nexubo","text":"Jangan berpikir begitu. Di dompet recovery phrase standar, jika frasanya hilang tanpa metode cadangan lain, tim dukungan tidak bisa memulihkannya untukmu."},{"t":84.25,"who":"nexubo","text":"Menyimpan aset di platform membawa risiko platform. Memegangnya sendiri bisa berisiko akibat kunci bocor atau salah approve. Hari ini pahami perbedaannya saja dulu."},{"t":103.25,"who":"narrator","text":"Siapa yang memegang izin memindahkan aset? Jawab itu dulu. Baru putuskan akun atau dompet apa yang kamu perlukan."},{"t":116.25,"who":"narrator","text":"Dua pintu tampak sama persis. Salah satunya palsu. Episode berikutnya: cara mengenali pintu yang asli."},{"t":121.75,"who":"narrator","text":"Pahami dulu, baru bertindak."}]},{"ep":4,"title":"Temukan pintu yang asli: Jangan buka akun sembarangan","goal":"Memeriksa domain resmi, ketentuan wilayah, dan mengaktifkan keamanan dasar sebelum mendaftar.","task":"Temukan kejanggalan pada bilah alamat di halaman pendaftaran tiruan.","answer":"Nama domain resminya tidak cocok. Jangan masukkan data di situs mencurigakan.","takeaways":["Sebelum hal lain, pastikan platform melayani negara tempat Anda benar-benar tinggal.","Daftar hanya melalui pintu masuk resmi yang sudah dikonfirmasi, dengan email atau nomor telepon Anda sendiri.","Segera setelah mendaftar, aktifkan fitur keamanan dan simpan opsi pemulihan Anda."],"quiz":{"q":"Apa yang harus Anda pastikan lebih dulu sebelum mendaftar?","options":["Besarnya hadiah sambutan","Bahwa platform melayani negara Anda dan pintu masuknya resmi","Berapa banyak pengikut platform tersebut"],"answer":1,"why":"Kelayakan dan pintu masuk resmi datang lebih dulu. Hadiah tidak boleh menentukan di mana Anda membuka akun."},"transcript":[{"t":0.25,"who":"sam","text":"Saya cari 'bursa' di internet dan ada sepuluh link mirip. Mana yang asli?"},{"t":9.25,"who":"nexubo","text":"Jangan asal klik. Sebelum daftar, periksa empat hal: domain resmi, ketentuan wilayah, ketersediaan produk, dan keamanan akun."},{"t":32.25,"who":"narrator","text":"Setelah memastikan akses resmi, daftarlah dengan email atau nomor ponselmu sendiri, buat kata sandi unik, dan selesaikan verifikasi. Jangan pernah beli akun orang lain atau memalsukan identitas."},{"t":60.25,"who":"nexubo","text":"Mendaftar bukan langkah terakhir. Pasang fitur keamanan yang didukung, periksa perangkat login, dan simpan cara pemulihan. Jangan pernah beri kode OTP ke orang yang mengaku CS."},{"t":84.25,"who":"narrator","text":"Situs kami membantu mencari informasi, tapi kerja sama promosi bukan jaminan keamanan. Jika data belum terkonfirmasi, jangan mulai proses buka akun."},{"t":103.25,"who":"sam","text":"Berhenti. Pastikan kelayakan dan aturannya dulu."},{"t":107.02,"who":"nexubo","text":"Tepat. Kenali pintunya, baru buka akunnya."},{"t":116.25,"who":"nexubo","text":"Mau pintu yang terpercaya? NexuAlpha mencantumkan akses resmi terverifikasi. Tautan mitra OKX kami langsung ke situs resmi, dan kode nexu888 memberikan rebate biaya."},{"t":127.35,"who":"narrator","text":"Lakukan sekarang: aktifkan autentikasi dua langkah. Berikutnya: seseorang di obrolan menawarkan 'jasa lolos KYC'."},{"t":134.45,"who":"narrator","text":"Pahami dulu, baru bertindak."}]},{"ep":5,"title":"Bagaimana cara kerja KYC dan kepada siapa identitas diberikan?","goal":"Memahami tujuan umum dan alur verifikasi identitas, serta hanya mengirimkannya lewat saluran resmi terverifikasi.","task":"Urutkan langkah verifikasi memakai data fiktif. Dilarang mengunggah kartu identitas asli di kursus.","answer":"Verifikasi akses resmi → kirim data asli sesuai syarat wilayah → tunggu dan periksa hasilnya.","takeaways":["KYC memastikan bahwa Anda pemilik akun dan membantu platform memenuhi aturan.","Kirim identitas Anda hanya di dalam alur verifikasi resmi, jangan pernah lewat chat.","Jika gagal, baca alasannya, perbaiki, lalu coba lagi dengan identitas asli Anda."],"quiz":{"q":"Siapa yang boleh menerima identitas Anda?","options":["\"Agen\" yang ramah di grup chat","Hanya alur verifikasi resmi yang sudah terverifikasi","Chat kursus, supaya orang lain bisa memeriksanya"],"answer":1,"why":"Hanya alur resmi. NexuAlpha tidak pernah meminta identitas Anda, dan orang asing pun tidak seharusnya meminta."},"transcript":[{"t":0.25,"who":"sam","text":"Sistem meminta kartu identitas saya. Dan orang ini bilang bisa mengurusnya untuk saya?"},{"t":9.25,"who":"nexubo","text":"Verifikasi identitas bertujuan memastikan pemilik akun dan memenuhi aturan. Pastikan alurnya resmi, jangan serahkan kartu identitas atau kode ke 'calo' di grup obrolan."},{"t":32.25,"who":"narrator","text":"Biasanya kamu mengisi data asli, mengunggah identitas valid yang didukung, lalu mengikuti petunjuk foto atau verifikasi wajah. Dokumen yang diterima tergantung wilayah dan platformmu."},{"t":60.25,"who":"nexubo","text":"Jika gagal, cari tahu penyebabnya: Apakah kedaluwarsa? Silau? Nama tidak cocok? Perbaiki sesuai petunjuk, jangan coba-coba pakai identitas palsu."},{"t":84.25,"who":"sam","text":"Setelah selesai, apakah bisa langsung trading?"},{"t":86.78,"who":"nexubo","text":"Tidak dijamin. Hasil peninjauan, akses produk, dan izin deposit bergantung pada pemberitahuan resmi. Dan akademi ini tidak pernah mengumpulkan identitas aslimu."},{"t":103.25,"who":"narrator","text":"Kepada siapa identitas diberikan? Hanya ke alur resmi terverifikasi. Bukan ke kami, dan bukan ke orang asing."},{"t":116.25,"who":"nexubo","text":"Siap verifikasi? Mulai hanya di situs resmi. Tautan mitra OKX kami mengarahkan langsung ke sana, dengan kode nexu888 untuk rebate biaya. Kami tidak pernah meminta identitasmu."},{"t":127.25,"who":"narrator","text":"Deposit, beli, transfer: tiga tombol yang tampak serupa. Berikutnya: tombol mana yang harus ditekan."},{"t":132.85,"who":"narrator","text":"Pahami dulu, baru bertindak."}]},{"ep":6,"title":"Deposit pertama: dari mana uang masuk dan ke mana perginya?","goal":"Membedakan deposit fiat, pembelian langsung, deposit kripto, dan transfer internal; memeriksa jalur dan biaya.","task":"Cocokkan tiga skenario: deposit fiat via bank, deposit kripto yang sudah dimiliki, dan transfer saldo internal antar-akun.","answer":"Jalur berbeda memiliki aturan, biaya, dan waktu berbeda. Transfer internal tidak menggunakan blockchain.","takeaways":["Deposit fiat, membeli kripto, deposit on-chain, dan transfer internal adalah jalur yang berbeda.","Deposit on-chain memerlukan koin dan jaringan yang didukung; transfer internal tetap di dalam platform.","Jangan pernah membayar orang asing di luar platform; periksa dulu ke mana saldo akan masuk."],"quiz":{"q":"Anda memindahkan USDT dari akun pendanaan ke akun trading di platform yang sama. Itu disebut apa?","options":["Deposit on-chain","Transfer internal","Deposit fiat"],"answer":1,"why":"Itu hanya memindahkan saldo antar akun Anda sendiri. Biasanya bukan transfer on-chain."},"transcript":[{"t":0.25,"who":"sam","text":"Ada tiga tombol: deposit, beli, dan transfer. Bukankah semuanya buat memasukkan uang?"},{"t":9.25,"who":"nexubo","text":"Bukan. Fungsinya memindahkan aset yang berbeda. Apakah kamu memasukkan mata uang lokal atau kripto yang sudah ada? Atau sekadar memindahkan saldo antar-akunmu?"},{"t":32.25,"who":"narrator","text":"Deposit fiat biasanya menambah saldo uang tunai akunmu. Beli kripto langsung berarti kamu membayar dan menerima aset kripto. Jalur bank atau kartu, biaya, dan batasannya berbeda di tiap platform."},{"t":60.25,"who":"nexubo","text":"Jika sudah punya kripto, depositkan lewat koin dan jaringan yang didukung. Transfer internal hanya memindahkan saldo antar-akun, biasanya tanpa blockchain. Pastikan dulu saldo masuk ke mana."},{"t":84.25,"who":"narrator","text":"Beberapa platform menyediakan perdagangan antar-pengguna (P2P). Itu bukan nama lain dari transfer bank biasa. Jangan pernah bayar di luar platform atau pakai dana dari pihak ketiga."},{"t":103.25,"who":"sam","text":"Tidak bisa. Itu jalur yang berbeda."},{"t":105.59,"who":"nexubo","text":"Benar. Lihat asetnya dulu, lalu jalurnya, dan terakhir periksa apa yang benar-benar masuk."},{"t":116.25,"who":"narrator","text":"BTC/USDT: apakah garis miring itu artinya beli dua koin? Berikutnya: perdagangan spot pertamamu."},{"t":122.45,"who":"narrator","text":"Pahami dulu, baru bertindak."}]},{"ep":7,"title":"Trading spot pertamamu: dari 100 USDT jadi 0,002 BTC","goal":"Menyelesaikan simulasi beli spot dengan nominal, jumlah koin, dan biaya yang jelas.","task":"Dengan saldo virtual 1,000, beli 0.002 BTC. Periksa sisa saldo 899.90 USDT dan riwayat transaksinya.","answer":"Nominal 100, biaya 0.10, total pengeluaran 100.10; sisa 899.90.","takeaways":["BTC/USDT berarti bitcoin yang dihargai dalam USDT: Anda membayar USDT dan menerima bitcoin.","Periksa apakah kolom order meminta jumlah uang atau jumlah koin.","Setelah membeli, periksa catatan transaksi: status eksekusi, harga rata-rata, dan biaya."],"quiz":{"q":"Anda membeli 0.002 BTC di harga 50,000 dengan biaya 0.1% yang dipotong terpisah dalam USDT. Berapa total yang dibelanjakan?","options":["100","100.10","110"],"answer":1,"why":"100 untuk koinnya ditambah biaya 0.10 menjadi 100.10."},"transcript":[{"t":0.25,"who":"sam","text":"Garis miring ini. Apakah saya harus beli kedua koinnya?"},{"t":9.25,"who":"nexubo","text":"Bukan. Itu artinya bitcoin dihargai dalam USDT. Saat beli, kamu membayar USDT dan dapat bitcoin. Saat jual, kebalikannya."},{"t":35.25,"who":"narrator","text":"Kita latihan pakai akun virtual. Pastikan mode spot, bukan futures. Pilih pasangan, klik Beli, lalu masukkan nominalnya. Periksa apakah kolom meminta uang atau jumlah koin."},{"t":67.25,"who":"nexubo","text":"Misal harga eksekusi 50,000 dan kamu beli 100. Kamu dapat 0.002 bitcoin. Anggap ada biaya 0.1% dipotong terpisah dari USDT, total belanjamu 100.10. Aturan asli tergantung platform."},{"t":95.25,"who":"sam","text":"Jadi begitu klik Beli, koinnya langsung pasti ada?"},{"t":99.07,"who":"nexubo","text":"Periksa juga riwayat transaksi. Belum terisi, terisi sebagian, dan terisi penuh itu berbeda. Cek juga harga rata-rata riil dan biayanya."},{"t":116.25,"who":"narrator","text":"Latihan pertama ini bukan untuk menebak naik turunnya harga. Ini untuk memastikan lima hal ini. Setelah selesai, tidak apa-apa jika belum mau trading riil."},{"t":131.25,"who":"nexubo","text":"Saat siap untuk trading riil pertama, buka Bitget lewat tautan mitra kami. Kode nexu888 memberikan rabat sebagian biaya trading. Lakukan lima pengecekan yang sama setiap kali bertransaksi."},{"t":140.95,"who":"narrator","text":"Misalkan harga naik lalu kamu jual. Kenapa saldo rekening bankmu tetap tidak berubah? Di episode berikutnya."},{"t":146.85,"who":"narrator","text":"Pahami dulu, baru bertindak."}]},{"ep":8,"title":"Saya sudah jual. Mengapa uangnya belum masuk ke rekening bank?","goal":"Membedakan antara menjual aset, menerima saldo stablecoin atau fiat, dan penarikan riil ke rekening bank.","task":"Selesaikan simulasi jual, lalu tandai pada diagram aliran dana langkah mana yang merupakan penarikan ke bank.","answer":"Menjual ke USDT bukan penarikan ke bank. Hasil trading bersih di contoh ini: 9.79.","takeaways":["Menjual ke USDT memberi Anda saldo USDT, bukan uang di bank Anda.","Menjual dan menarik ke bank adalah dua langkah terpisah.","Harga yang lebih tinggi bukan keuntungan bersih Anda: kurangi semua biaya dulu."],"quiz":{"q":"Anda menjual bitcoin ke USDT. Di mana uangnya sekarang?","options":["Di rekening bank Anda","Sebagai saldo USDT di platform","Sudah dikonversi ke mata uang lokal Anda"],"answer":1,"why":"Anda menerima USDT. Memindahkan uang ke bank adalah langkah penarikan yang terpisah."},"transcript":[{"t":0.25,"who":"sam","text":"Saya jelas-jelas sudah jual. Lalu kenapa rekening bank saya belum terima uangnya?"},{"t":9.25,"who":"nexubo","text":"Lihat dulu kamu menjual ke pasangan apa. Kalau jual ke USDT, kamu menerima saldo USDT, bukan uang di bank. Menjual dan menarik ke bank adalah dua langkah terpisah."},{"t":35.25,"who":"narrator","text":"Contoh belajar yang sama. Kamu jual 0.002 bitcoin di harga 55,000, totalnya 110. Dikurangi biaya asumsi 0.11, masuk 109.89 ke akunmu."},{"t":67.25,"who":"sam","text":"Jadi saya untung sepuluh?"},{"t":68.76,"who":"nexubo","text":"Kurangi biayanya. Di sini 9.79, belum termasuk kemungkinan biaya konversi atau penarikan. Kenaikan harga tidak sama dengan keuntungan bersih akhirmu."},{"t":95.25,"who":"narrator","text":"Jika butuh uang kembali ke bank, cek dulu apakah wilayahmu mendukung. Lalu tarik lewat jalur resmi ke rekening atas nama sendiri. Periksa nama, nominal masuk, biaya, dan syarat prosesnya."},{"t":116.25,"who":"sam","text":"Bukan."},{"t":116.98,"who":"nexubo","text":"Simpan riwayat transaksi dan penarikanmu. Jika ragu dengan sifat saldonya, jangan ambil keputusan hanya dari tulisan 'sukses'."},{"t":131.25,"who":"narrator","text":"Jaringan lebih murah. Sekali salah klik. Koinmu bisa lenyap selamanya. Berikutnya: hal-hal yang tidak boleh ditebak-tebak."},{"t":137.95,"who":"narrator","text":"Pahami dulu, baru bertindak."}]},{"ep":9,"title":"Sebelum transfer: jangan tebak-tebak hal-hal ini","goal":"Memeriksa koin, jaringan, alamat, memo, dan syarat penerimaan, serta kirim uji coba nominal kecil dulu.","task":"Pada formulir penarikan tiruan yang sengaja dibuat salah, perbaiki jaringan yang tidak cocok dan memo yang hilang; lalu kirim uji coba virtual nominal kecil.","answer":"Kirim hanya saat semua syarat utama cocok. Tidak ada perlindungan default 'otomatis beralih ke jaringan yang benar'.","takeaways":["Pastikan koin dan jaringan yang didukung penerima sebelum Anda mengirim.","Salin alamat dari halaman penerimaan, periksa seluruhnya, dan tambahkan memo atau tag jika ada.","Kirim tes kecil dulu dan pastikan sudah masuk ke saldo."],"quiz":{"q":"Halaman penerimaan meminta memo. Apa yang Anda lakukan?","options":["Lewati saja, alamat sudah cukup","Isi memo persis seperti yang ditampilkan","Pakai memo dari transfer lama"],"answer":1,"why":"Jika memo atau tag diwajibkan, transfer bisa tidak masuk ke saldo tanpanya."},"transcript":[{"t":0.25,"who":"sam","text":"Jaringan ini lebih murah. Kenapa nggak langsung ganti ke situ saja?"},{"t":9.25,"who":"nexubo","text":"Konfirmasi dulu aset dan jaringan apa yang didukung penerima. Baru pertimbangkan biayanya. Jika kedua pihak tidak cocok, jangan kirim hanya karena murah. USDT pun ada di berbagai jaringan."},{"t":39.25,"who":"narrator","text":"Anggap jaringan sebagai rute dan alamat sebagai tujuan. Tapi dua alamat bisa mirip namun tidak kompatibel di jaringan yang sama. Selalu pastikan platform penerima mendukung rantai dan aset ini."},{"t":75.25,"who":"nexubo","text":"Salin alamat dari halaman penerima, lalu periksa lengkapnya. Isi memo atau tag jika diminta. Pastikan batas deposit minimum, biaya penarikan, dan nominal tiba. Jangan cuma lihat huruf depan dan belakang."},{"t":106.25,"who":"narrator","text":"Kirim uji coba kecil sesuai batas minimum, dan pastikan benar-benar masuk. Untuk transfer besar berikutnya, periksa ulang semuanya, jangan asal pakai riwayat lama. Di dompet mandiri, siapkan biaya jaringan."},{"t":130.25,"who":"sam","text":"Tidak boleh."},{"t":131.16,"who":"nexubo","text":"Mengecek sekali lagi sebelum kirim jauh lebih berharga daripada mencari bantuan setelah salah transfer."},{"t":146.25,"who":"narrator","text":"Tertulis 'sukses', tapi tidak ada yang masuk. Jangan kirim ulang. Berikutnya: ke mana harus mengecek."},{"t":151.65,"who":"narrator","text":"Pahami dulu, baru bertindak."}]},{"ep":10,"title":"Tertulis terkirim, tapi belum sampai. Harus cek ke mana?","goal":"Membedakan pemrosesan pengirim, konfirmasi di blockchain, dan pengkreditan penerima, serta tahu jalur pemulihan yang terbatas.","task":"Cocokkan tiga skenario kendala ke: pengirim, status blockchain, dan penerima.","answer":"Cari tahu statusnya lalu hubungi saluran resmi terkait. Jangan bayar ulang jika penyebabnya belum jelas.","takeaways":["Terkirim, on-chain, dan masuk ke saldo adalah tiga pos yang berbeda.","Gunakan hash transaksi di block explorer untuk jaringan yang benar.","Bagikan catatan kepada dukungan resmi, jangan pernah frasa pemulihan, kunci privat, atau kode Anda."],"quiz":{"q":"Transfer Anda berstatus \"terkirim\" tetapi belum tiba. Apa langkah pertama?","options":["Kirim jumlah yang sama lagi","Cari di mana transfer tertahan menggunakan catatan dan hash transaksi","Bayar orang yang berjanji bisa memulihkannya"],"answer":1,"why":"Temukan posnya dulu, lalu hubungi saluran resmi yang sesuai. Jangan terus mengirim."},"transcript":[{"t":0.25,"who":"sam","text":"Belum masuk. Apa saya coba kirim beberapa kali lagi?"},{"t":9.25,"who":"nexubo","text":"Jangan kirim lagi. Diajukan, masuk blockchain, dan masuk rekening itu berbeda. Cari tahu tersangkut di mana, baru putuskan siapa yang harus dihubungi."},{"t":32.25,"who":"narrator","text":"Simpan bukti kirim. Jika ada hash transaksi, periksa di block explorer resmi jaringan tersebut: status, alamat tujuan, dan nominalnya. Jangan campurkan dengan blockchain lain."},{"t":60.25,"who":"nexubo","text":"Platform penerima mungkin butuh konfirmasi tambahan atau peninjauan internal. Jika salah koin, jaringan, alamat, atau memo, berhenti kirim dan serahkan buktinya ke CS resmi."},{"t":84.25,"who":"narrator","text":"Transfer yang sudah tuntas di blockchain umumnya tidak bisa dibatalkan seperti transaksi biasa. Bisa dipulihkan atau tidak tergantung platform dan teknisnya. Jangan percaya yang minta bayaran untuk pulih."},{"t":103.25,"who":"sam","text":"Berikan bukti transaksi yang diperlukan. Jangan pernah berikan recovery phrase, kunci privat, atau kode OTP."},{"t":107.92,"who":"nexubo","text":"Benar. Cari tahu tersangkut di mana dulu. Jangan asal kirim terus."},{"t":116.25,"who":"narrator","text":"'Halo, saya tim dukungan. Kirimkan recovery phrase Anda.' Berikutnya: apa yang sebenarnya diincar penipu."},{"t":122.45,"who":"narrator","text":"Pahami dulu, baru bertindak."}]},{"ep":11,"title":"Ada yang bilang bisa bikin kamu kaya. Lihat dulu apa maunya.","goal":"Mengenali permintaan kredensial rahasia, pembayaran di luar platform, persetujuan mencurigakan, dan janji keuntungan.","task":"Temukan permintaan berbahaya di empat obrolan tiruan, lalu pilih tindakan 'berhenti dan verifikasi secara resmi'.","answer":"Jika ada yang meminta kunci privat, recovery phrase, kode OTP, atau persetujuan yang tidak jelas, jangan lakukan.","takeaways":["Frasa pemulihan dan kunci privat Anda adalah kunci kendali, bukan kode dukungan.","Imbal hasil yang dijamin dan desakan untuk membayar adalah tanda bahaya.","Jangan pernah mengonfirmasi tanda tangan atau persetujuan yang tidak Anda pahami."],"quiz":{"q":"Mana yang aman dibagikan agar Anda bisa menerima pembayaran?","options":["Alamat publik Anda","Frasa pemulihan Anda","Kode sekali pakai"],"answer":0,"why":"Alamat publik dibuat untuk menerima. Rahasia dan kode memberikan kendali kepada orang lain."},"transcript":[{"t":0.25,"who":"sam","text":"Dia mengaku CS dan mau membantu meningkatkan versi dompet saya."},{"t":9.25,"who":"nexubo","text":"Di dompet standar, recovery phrase adalah kunci kendali penuh, bukan kode verifikasi CS. Begitu juga kunci privat. Jangan pernah berikan ke siapa pun. Bahkan asisten akademi kami pun tidak boleh memintanya."},{"t":32.25,"who":"narrator","text":"Dua tanda bahaya lainnya: jaminan untung dan desakan bayar cepat. Tangkapan layar profit besar tidak membuktikan apa pun. Jika ada yang mendesakmu melompati langkah pengecekan, berhentilah."},{"t":60.25,"who":"nexubo","text":"Menghubungkan dompet, menandatangani pesan, dan memberi persetujuan akses aset itu tidak sama. Jika tidak paham tanda tangan atau approval-nya, jangan setujui. Tidak minta kata sandi bukan berarti aman."},{"t":84.25,"who":"narrator","text":"Jika mencurigai adanya kebocoran data, berhenti dan gunakan saluran keamanan resmi. Ambil tindakan sesuai apa yang bocor, jangan pernah instal aplikasi kendali jarak jauh atas arahan siapa pun."},{"t":103.25,"who":"sam","text":"Membagikan info untuk menerima dana bukan berarti menyerahkan kunci kendali."},{"t":106.72,"who":"nexubo","text":"Jangan bagi rahasia. Jangan asal setujui. Jangan mau diburu-buru bayar."},{"t":116.25,"who":"narrator","text":"Sebelas episode tuntas. Waktunya deposit uang asli? Episode penutup Musim 1 punya jawaban mengejutkan."},{"t":123.15,"who":"narrator","text":"Pahami dulu, baru bertindak."}]},{"ep":12,"title":"Penutup Musim 1: Kamu bisa melakukannya, dan boleh memilih untuk tidak trading","goal":"Menyelesaikan latihan terpadu, memahami bahwa tidak trading adalah pilihan yang sah, dan mengetahui langkah berikutnya.","task":"Jawab tiga pertanyaan penutup kursus di panel latihan.","answer":"Jual ke USDT bukan tarik uang ke bank; di blockchain bukan berarti masuk akun; jangan bagi kredensial atau transfer saat ragu.","takeaways":["Tujuannya adalah alur yang benar: pintu masuk dan kelayakan, spot, jumlah dan biaya, lalu catatan.","Menghentikan transfer yang tidak jelas juga merupakan jawaban yang benar.","Sertifikat Anda adalah catatan belajar, bukan izin untuk berinvestasi."],"quiz":{"q":"Transfer latihan menunjukkan jaringan yang salah. Apa langkah yang tepat?","options":["Tetap kirim dan berharap","Berhenti dan jangan kirim","Ganti ke jumlah yang lebih besar"],"answer":1,"why":"Saat jaringan, biaya, atau identitas tidak jelas, berhenti lebih penting daripada menyelesaikan tugas."},"transcript":[{"t":0.25,"who":"sam","text":"Saya sudah selesaikan semua pelajaran. Apakah artinya saya siap trading riil?"},{"t":9.25,"who":"nexubo","text":"Jangan buru-buru. Hari ini kita lakukan simulasi komprehensif. Periksa pintu masuk, spot, nominal dan biaya, lalu cek riwayatnya. Kalau ragu, jangan trading."},{"t":39.25,"who":"narrator","text":"Kamu berhasil jika bisa mengenali risiko dan mengecek dengan tenang. Skor latihan bukan jaminan keuntungan masa depan. Jika salah menjawab, ulangi pelajarannya."},{"t":75.25,"who":"sam","text":"Ada yang mencurigakan di transfer ini. Saya tidak mau kirim."},{"t":78.5,"who":"nexubo","text":"Itu juga jawaban yang benar. Saat jaringan, biaya, atau identitas belum jelas, berhenti jauh lebih penting daripada memaksakan transaksi."},{"t":106.25,"who":"narrator","text":"Terakhir, jawab tiga hal ini: Ke mana aset berpindah? Berapa nominal yang benar-benar terpotong? Siapa yang mengontrol akunmu? Jika ada yang ragu, pelajari lagi modulnya."},{"t":130.25,"who":"nexubo","text":"Yang kamu peroleh adalah catatan belajar, bukan izin investasi. Lanjut belajar atau tidak trading dulu, dua-duanya pilihan tepat. Pahami dulu, baru bertindak."},{"t":146.25,"who":"nexubo","text":"Saat memutuskan untuk mulai, bandingkan bursa di NexuAlpha. Daftar lewat tautan mitra resmi dengan kode kami untuk rebate biaya, dan gabung ke Telegram kami untuk pelajaran baru."},{"t":157.55,"who":"narrator","text":"Musim 2: harga di layarmu tidak selalu sama dengan yang kamu bayar. Cari tahu penyebabnya."},{"t":163.05,"who":"narrator","text":"Pahami dulu, baru bertindak."}]},{"ep":13,"title":"Mengapa harga di layar bukan harga eksekusi saya?","goal":"Memahami buku order, spread bid-ask, kedalaman pasar, biaya transaksi, dan slippage.","task":"Cocokkan 0.002 BTC pada dua tingkatan order jual virtual dan hitung harga rata-rata tertimbang.","answer":"Total 100.10, rata-rata 50,050 sebelum biaya latihan. Jika ada biaya 0.1% dalam USDT: biaya 0.1001, total 100.2001 (jangan bulatkan sebelum hitung).","takeaways":["Harga terakhir adalah transaksi terbaru, bukan penawaran untuk ukuran berapa pun.","Order yang lebih besar bisa tereksekusi di beberapa level order book.","Slippage dan biaya trading adalah biaya terpisah: periksa tagihannya."],"quiz":{"q":"Separuh dari 0.002 BTC Anda tereksekusi di 50,000 dan separuh lainnya di 50,100. Berapa harga rata-rata Anda?","options":["50,000","50,050","50,100"],"answer":1,"why":"Dua bagian yang sama besar rata-ratanya 50,050. Biaya adalah biaya terpisah di atasnya."},"transcript":[{"t":0.25,"who":"sam","text":"Semenit lalu harganya segini. Kenapa tagihan saya beda?"},{"t":9.25,"who":"nexubo","text":"Harga terakhir di layar adalah catatan transaksi terbaru, bukan penawaran jumlah tak terbatas. Berapa banyak yang ingin dibeli dan dijual saat ini tercatat di buku order."},{"t":32.25,"who":"narrator","text":"Misal kamu beli 0.002 bitcoin. Level pertama hanya ada setengahnya. Setengah sisanya terisi di harga lebih tinggi. Rata-ratanya jadi 50,050, bukan 50,000."},{"t":60.25,"who":"nexubo","text":"Slippage adalah selisih antara harga perkiraan dan harga yang didapat. Tidak selalu merugikan. Biaya trading adalah beban terpisah. Jangan campur adukkan dalam slogan 'gratis'."},{"t":84.25,"who":"narrator","text":"Order besar, kedalaman tipis, atau pasar bergerak cepat memperbesar selisih harga dari perkiraan. Cek ukuran dan kedalaman sebelum order, cek rata-rata riil sesudahnya."},{"t":103.25,"who":"sam","text":"Tidak bisa."},{"t":104.04,"who":"nexubo","text":"Kamu baru tahu hasil eksekusi setelah melihat rincian tagihannya. Jangan cuma terpaku pada angka paling besar."},{"t":116.25,"who":"nexubo","text":"Biaya transaksi adalah biaya yang bisa kamu kurangi. Bandingkan biaya di NexuAlpha, dan daftar lewat tautan mitra dengan kode kami untuk rebate biaya. Biaya lebih rendah, risiko tetap sama."},{"t":126.75,"who":"narrator","text":"Pasang order beli tapi tidak ada yang terjadi. Apakah rusak? Berikutnya: order pasar, limit, dan pembatalan."},{"t":132.45,"who":"narrator","text":"Pahami dulu, baru bertindak."}]},{"ep":14,"title":"Order market, limit, dan pembatalan: apa fungsi masing-masing?","goal":"Pilih pesanan berdasarkan 'eksekusi dulu' atau 'batas harga dulu', dan pahami pesanan yang belum terpenuhi dan terisi sebagian.","task":"Pasang pesanan limit virtual, amati eksekusi sebagian, lalu batalkan sisa jumlahnya.","answer":"Bahkan dengan kondisi harga yang tepat, hal itu dipengaruhi oleh jumlah yang tersedia; bagian yang sudah terisi tidak dapat dibalikkan dengan pembatalan.","takeaways":["Market order tereksekusi cepat di harga yang tersedia saat ini; harga akhirnya bisa bergeser.","Limit order membatasi harga Anda, tetapi mungkin tidak tereksekusi.","Pembatalan hanya memengaruhi bagian yang belum tereksekusi; yang sudah tereksekusi tetap."],"quiz":{"q":"Limit order Anda baru tereksekusi separuh dan Anda membatalkannya. Apa yang terjadi?","options":["Semuanya dibatalkan kembali","Hanya separuh yang belum tereksekusi yang dibatalkan","Separuh yang tereksekusi berubah menjadi market order"],"answer":1,"why":"Pembatalan tidak bisa memutar balik eksekusi. Itu hanya menghentikan sisa jumlahnya."},"transcript":[{"t":0.25,"who":"sam","text":"Saya sudah menekan beli. Mengapa belum terisi juga?"},{"t":9.25,"who":"nexubo","text":"Pesanan pasar memprioritaskan penyelesaian cepat pada kuotasi yang tersedia saat ini, tetapi harga akhir dapat berubah. Pesanan limit menetapkan batas beli tidak lebih tinggi atau jual tidak lebih rendah dari harga tertentu, tanpa jaminan eksekusi."},{"t":32.25,"who":"narrator","text":"Jika ingin membeli di bawah harga saat ini, Anda mungkin harus menunggu. Sebaliknya, jika pesanan limit sudah memenuhi penawaran lawan, pesanan itu bisa langsung terisi; tidak semua pesanan limit harus mengantre."},{"t":60.25,"who":"sam","text":"Lalu apakah membatalkan pesanan juga membatalkan apa yang baru saja saya beli?"},{"t":62.82,"who":"nexubo","text":"Tidak. Pembatalan hanya memproses bagian yang belum terisi; perubahan aset yang sudah dieksekusi tidak dapat diputar balik."},{"t":84.25,"who":"narrator","text":"Periksa statusnya sebelum bertindak. Menjadi maker atau taker tergantung pada cara eksekusi sebenarnya; memilih pesanan limit tidak menjamin tarif biaya tertentu."},{"t":103.25,"who":"sam","text":"Tidak."},{"t":104.12,"who":"nexubo","text":"Memilih pesanan berarti memilih metode eksekusi, bukan membuat permohonan."},{"t":116.25,"who":"narrator","text":"Apakah candle hijau berarti candle berikutnya juga akan naik? Di episode berikutnya."},{"t":121.05,"who":"narrator","text":"Pahami dulu, baru bertindak."}]},{"ep":15,"title":"Satu candle: empat hal apa yang diceritakannya kepadamu?","goal":"Baca harga buka, tertinggi, terendah, tutup dan kerangka waktu; jangan menganggap warna atau satu bentuk sebagai prediksi.","task":"Klik buka, tertinggi, terendah, tutup pada candle virtual dan konfirmasi kerangka waktu grafik.","answer":"50,000 / 51,000 / 49,000 / 50,500; periode lima menit.","takeaways":["Satu candle menunjukkan empat harga untuk satu periode: pembukaan, tertinggi, terendah, dan penutupan.","Baca time frame sebelum bentuknya: lima menit bukan satu hari.","Warna berbeda antar aplikasi, dan satu candle adalah catatan, bukan prediksi."],"quiz":{"q":"Candle lima menit dibuka di 50,000, naik ke 51,000, turun ke 49,000, dan ditutup di 50,500. Berapa harga tertingginya?","options":["50,500","51,000","49,000"],"answer":1,"why":"Puncak sumbu atas adalah harga tertinggi pada periode itu: 51,000."},"transcript":[{"t":0.25,"who":"sam","text":"Hijau, apakah berarti detik berikutnya akan naik lagi?"},{"t":9.25,"who":"nexubo","text":"Satu candle mencatat empat harga dari suatu periode: buka, tertinggi, terendah, dan tutup. Ini adalah pasar fiktif lima menit, bukan jaminan untuk lima menit ke depan."},{"t":32.25,"who":"narrator","text":"Body membantu Anda melihat selisih antara buka dan tutup; sumbu menandai titik tertinggi dan terendah yang pernah dicapai. Candle yang belum selesai akan terus berubah seiring perdagangan baru."},{"t":60.25,"who":"sam","text":"Mengapa grafik terlihat berbeda saat berpindah kerangka waktu?"},{"t":63.75,"who":"nexubo","text":"Panjang waktu yang diwakili setiap candle telah berubah. Baca kerangka waktu dulu sebelum membahas bentuknya; jangan perlakukan lima menit seperti satu hari."},{"t":84.25,"who":"narrator","text":"Aplikasi berbeda dapat menggunakan warna berbeda untuk naik atau turun, jadi perhatikan legenda dan angkanya. Tren historis memberikan informasi, tetapi satu candle tidak menjamin pergerakan selanjutnya."},{"t":103.25,"who":"sam","text":"Tertinggi 51,000, tutup 50,500."},{"t":108.91,"who":"nexubo","text":"Baca catatannya dulu, jangan jadikan catatan sebagai ramalan."},{"t":116.25,"who":"narrator","text":"\"Saya punya 1,000, cuma mau rugi 20, beli semua saja?\" Berikutnya: tentukan batas rugi dulu."},{"t":122.35,"who":"narrator","text":"Pahami dulu, baru bertindak."}]},{"ep":16,"title":"Tentukan batas kerugian sebelum memutuskan berapa banyak yang dibeli","goal":"Pahami bahwa saldo akun, ukuran posisi, dan risiko terencana adalah tiga angka yang berbeda.","task":"Hitung posisi virtual dengan data masuk, jarak stop-loss, dan anggaran risiko pengajaran yang diberikan.","answer":"Nilai nosional spot 400 USDT; 0.008 BTC; biaya dan deviasi eksekusi harus dihitung terpisah.","takeaways":["Saldo akun, ukuran posisi, dan risiko yang direncanakan adalah tiga angka yang berbeda.","Tentukan titik keluar dulu, baru tentukan ukuran posisi.","Dengan stop 5% dan anggaran risiko 20, posisinya sekitar 400."],"quiz":{"q":"Masuk di 50,000, rencana keluar di 47,500, dan Anda siap rugi 20. Kira-kira seberapa besar posisinya?","options":["20","400","4,000"],"answer":1,"why":"Titik keluar berjarak 5%, dan 5% dari 400 adalah 20. Biaya dihitung di atasnya."},"transcript":[{"t":0.25,"who":"sam","text":"Saya punya 1,000 dan hanya ingin rugi 20, jadi beli semuanya dulu?"},{"t":9.25,"who":"nexubo","text":"Berapa banyak di akun, berapa banyak yang Anda beli kali ini, dan berapa kerugian terencana yang Anda tanggung adalah tiga hal yang berbeda. Anda baru bisa memperkirakan posisi setelah memiliki rencana keluar."},{"t":35.25,"who":"narrator","text":"Lihat satu soal latihan: masuk di 50,000, rencana keluar di 47,500, selisih 5%. Mengabaikan biaya, jika Anda berencana menanggung risiko harga 20, posisinya sekitar 400."},{"t":67.25,"who":"sam","text":"Jadi 'hanya rugi 20' tidak sama dengan 'hanya membeli 20'?"},{"t":70.55,"who":"nexubo","text":"Benar. Di sini posisi 400 yang turun 5% bernilai 20; ini hanya parameter pengajaran."},{"t":95.25,"who":"narrator","text":"Pasar nyata memiliki slippage, gap, biaya, atau kegagalan eksekusi, sehingga risiko terencana bukan batas atas yang dijamin. Jangan meminjam uang untuk menyelesaikan kursus dan jangan gunakan dana kebutuhan hidup."},{"t":116.25,"who":"sam","text":"Dua puluh."},{"t":116.98,"who":"nexubo","text":"Hitung dulu skenario terburuk yang bisa Anda terima, baru putuskan apakah Anda membutuhkan perdagangan ini."},{"t":131.25,"who":"narrator","text":"Apakah memasang stop-loss berarti Anda hanya akan kehilangan jumlah itu? Berikutnya: kebenaran tentang stop-loss."},{"t":137.75,"who":"narrator","text":"Pahami dulu, baru bertindak."}]},{"ep":17,"title":"Take-profit dan stop-loss adalah rencana, bukan asuransi","goal":"Pahami perbedaan pemicu vs eksekusi, serta perbedaan risiko antara pesanan stop-market dan stop-limit.","task":"Bandingkan hasil latihan pesanan stop-market dan stop-limit dalam penurunan tajam yang sama.","answer":"Yang pertama bisa mengalami slippage; yang kedua mungkin tidak terisi. Keduanya bukan asuransi perlindungan modal.","takeaways":["Stop-loss menjalankan rencana keluar Anda; itu bukan asuransi.","Stop-market keluar dengan cepat tetapi bisa tergelincir di pasar yang bergerak cepat.","Stop-limit membatasi harga tetapi mungkin sama sekali tidak tereksekusi."],"quiz":{"q":"Saat harga anjlok tajam, apa yang bisa terjadi pada order stop-limit?","options":["Selalu tereksekusi di harga pemicu","Bisa tidak tereksekusi jika harga melesat melewatinya","Berubah menjadi asuransi"],"answer":1,"why":"Limit melindungi harga Anda, sehingga order bisa tetap tidak tereksekusi saat pasar bergerak cepat."},"transcript":[{"t":0.25,"who":"sam","text":"Stop-loss saya sudah diatur, jadi saya hanya akan rugi sejumlah yang saya ketik, kan?"},{"t":9.25,"who":"nexubo","text":"Stop-loss menjalankan rencana keluar saat kondisi terpenuhi, bukan asuransi. Kondisi yang terpicu tidak berarti pasti dieksekusi pada harga tersebut, juga tidak menjamin kerugian berhenti tepat di sana."},{"t":32.25,"who":"narrator","text":"Setelah terpicu, pesanan dieksekusi pada harga pasar untuk keluar cepat, tetapi harga sebenarnya dapat mengalami slippage. Saat pasar bergerak cepat atau likuiditas tipis, selisihnya bisa lebih besar."},{"t":60.25,"who":"nexubo","text":"Setelah terpicu, pesanan limit dipasang untuk membatasi harga yang diterima, namun bisa gagal terjual jika harga menembus terlalu cepat. Tidak ada yang selalu lebih baik; ini adalah kompromi yang berbeda."},{"t":84.25,"who":"narrator","text":"Periksa arah, jumlah, dan status pesanan setelah mengatur. Di futures, periksa juga jenis harga pemicu agar stop-loss tidak diletakkan di titik yang bisa terkena likuidasi lebih dulu."},{"t":103.25,"who":"sam","text":"Tidak dijamin."},{"t":104.72,"who":"nexubo","text":"Memahami batasan memungkinkan Anda memperlakukan stop-loss sebagai rencana efektif, bukan jimat keberuntungan."},{"t":116.25,"who":"narrator","text":"Keduanya tertulis BTC. Tapi yang satu mungkin tidak memberi Anda bitcoin sama sekali. Berikutnya: spot vs futures."},{"t":123.15,"who":"narrator","text":"Pahami dulu, baru bertindak."}]},{"ep":18,"title":"Spot vs futures: kamu tidak membeli hal yang sama","goal":"Bedakan memegang aset dengan memegang kontrak harga, dan pahami arah posisi long dan short.","task":"Cocokkan saldo aset spot dan bidang posisi futures ke halaman yang benar.","answer":"Posisi futures tidak setara dengan aset koin dasar yang dapat ditarik; kursus tidak meminta Anda membuka akun nyata.","takeaways":["Spot menukar satu aset dengan aset lain; perpetual adalah posisi kontrak.","Long untung jika harga naik, short untung jika harga turun; sisi yang salah rugi.","Futures adalah struktur risiko yang berbeda, bukan level yang harus Anda capai."],"quiz":{"q":"Apakah posisi futures memberi Anda bitcoin yang bisa ditarik?","options":["Ya, sama seperti spot","Tidak, itu kontrak yang menyelesaikan untung dan rugi","Hanya dengan leverage 10x"],"answer":1,"why":"Perpetual linear menyelesaikan untung dan rugi di dalam kontrak. Itu bukan saldo koin yang bisa ditarik."},"transcript":[{"t":0.25,"who":"sam","text":"Keduanya tertulis Bitcoin, bukankah ini perdagangan yang sama?"},{"t":9.25,"who":"nexubo","text":"Spot biasa tanpa pinjaman menukar satu aset dengan aset lain. Kontrak perpetual linier di sini memegang posisi kontrak yang menyelesaikan laba rugi berdasarkan perubahan harga, bukan membeli bitcoin yang dapat ditarik."},{"t":32.25,"who":"narrator","text":"Posisi long biasanya berharap harga naik, posisi short berharap harga turun. Salah menebak arah akan membuat kedua sisi merugi. Bisa melakukan short bukan berarti lebih mudah menghasilkan uang."},{"t":60.25,"who":"sam","text":"Haruskah saya beralih dari spot ke futures?"},{"t":62.38,"who":"nexubo","text":"Tidak perlu. Futures adalah struktur risiko yang berbeda, bukan tingkat keharusan belajar; mengetahui apa itu juga memungkinkan Anda memilih untuk tidak menggunakannya."},{"t":84.25,"who":"narrator","text":"Spot biasa tanpa pinjaman tidak memiliki likuidasi akibat margin tidak cukup seperti kontrak, namun aset tetap dapat mengalami depresiasi tajam. Tidak adanya likuidasi paksa bukan berarti modal terlindungi."},{"t":103.25,"who":"sam","text":"Bukan."},{"t":103.9,"who":"nexubo","text":"Pahami dulu apa yang Anda perdagangkan sebelum mempelajari leverage."},{"t":116.25,"who":"narrator","text":"Pada 10x, apakah platform memberi Anda 900 gratis? Di episode berikutnya."},{"t":121.25,"who":"narrator","text":"Pahami dulu, baru bertindak."}]},{"ep":19,"title":"Leverage 10x: lebih banyak uang, atau lebih banyak risiko?","goal":"Bedakan margin, posisi nosional, dan pengembalian margin; pahami efek pengaturan leverage pada ukuran posisi tetap.","task":"Pilih mode margin tetap dan posisi tetap secara terpisah, lalu amati laba rugi uang setelah perubahan harga.","answer":"Dengan margin tetap, menaikkan leverage memperbesar posisi nosional; dengan posisi tetap, itu tidak otomatis memperbesar laba atau rugi uang.","takeaways":["Margin 100 yang mengendalikan posisi 1,000 berarti leverage 10x.","Pergerakan harga berlaku pada posisi, dan margin Anda yang menanggung hasilnya.","Dengan ukuran posisi yang sama, mengubah leverage mengubah margin, bukan P&L."],"quiz":{"q":"Posisi 1,000 bergerak 1% melawan Anda, tanpa menghitung biaya. Kira-kira berapa kerugian Anda?","options":["1","10","100"],"answer":1,"why":"1% dari posisi 1,000 kira-kira 10, diambil dari margin Anda."},"transcript":[{"t":0.25,"who":"sam","text":"Pada sepuluh kali, apakah platform memberi saya 900 secara cuma-cuma?"},{"t":9.25,"who":"nexubo","text":"Bukan uang tunai gratis. Secara sederhana, margin 100 mengendalikan posisi nosional 1,000 adalah leverage 10x. Perubahan harga bekerja pada posisi, dan margin Anda menanggung laba rugi terkait."},{"t":35.25,"who":"narrator","text":"Mengabaikan biaya, jika harga bergerak 1% melawan Anda, posisi 1,000 merugi sekitar 10, dan posisi 2,000 merugi sekitar 20. Persentase kecil bisa sangat berdampak pada margin kecil."},{"t":67.25,"who":"nexubo","text":"Kekeliruan umum lainnya: jika ukuran posisi tetap sama dan Anda hanya menyesuaikan leverage, laba rugi uang untuk perubahan harga yang sama tidak berlipat ganda tiba-tiba; yang berubah adalah kebutuhan margin dan bantalan risiko."},{"t":95.25,"who":"narrator","text":"Likuidasi nyata melibatkan margin pemeliharaan, harga mark, dan biaya; 10x tidak berarti dilikuidasi tepat pada penurunan 10%. Jangan gunakan perkiraan ini untuk berdagang secara nyata."},{"t":116.25,"who":"sam","text":"Tidak."},{"t":117.06,"who":"nexubo","text":"Yang diperbesar adalah dampak posisi terhadap modal Anda, bukan kemampuan analisis Anda."},{"t":131.25,"who":"narrator","text":"Mengapa posisi Anda bisa ditutup sebelum margin menyentuh nol? Berikutnya: garis tak terlihat itu."},{"t":137.05,"who":"narrator","text":"Pahami dulu, baru bertindak."}]},{"ep":20,"title":"Mengapa posisimu bisa ditutup sebelum marginmu menyentuh nol?","goal":"Bedakan antara margin awal, margin pemeliharaan, ekuitas, dan saldo yang tersedia.","task":"Dengan awal 100 dan floating loss 20 (tanpa biaya), hitung ekuitas sederhana 80; kenali bidang yang berubah.","answer":"Ekuitas 80; persyaratan pemeliharaan harus dihitung terpisah berdasarkan aturan produk, jangan dianggap sama dengan margin awal.","takeaways":["Margin awal membuka posisi; margin pemeliharaan menjaganya tetap terbuka.","Ekuitas adalah margin ditambah atau dikurangi hasil yang masih berjalan: 100 turun 20 menyisakan 80.","Sistem risiko bisa turun tangan sebelum margin Anda mencapai nol."],"quiz":{"q":"Margin awal 100 dan posisi rugi 20, tanpa menghitung biaya. Berapa ekuitas yang disederhanakan?","options":["100","80","120"],"answer":1,"why":"100 dikurangi kerugian 20 menyisakan 80, dan bantalannya terus menyusut jika harga bergerak makin melawan Anda."},"transcript":[{"t":0.25,"who":"sam","text":"Masih ada saldo, mengapa saya tidak dibiarkan terus menunggu?"},{"t":9.25,"who":"nexubo","text":"Membuka posisi memerlukan margin awal; selama memegang posisi, Anda juga harus memenuhi persyaratan margin pemeliharaan. Berapa yang Anda masukkan di awal tidak sama dengan bantalan risiko seterusnya."},{"t":35.25,"who":"narrator","text":"Katakanlah margin awal adalah 100, floating loss adalah 20, mengabaikan hal lain, ekuitas yang tersisa hanya 80. Jika harga terus bergerak merugikan, bantalan yang tersedia akan terus menyusut."},{"t":67.25,"who":"nexubo","text":"Ketika ekuitas mendekati tingkat pemeliharaan yang diwajibkan platform, sistem risiko dapat mengambil tindakan; tidak harus menunggu sampai semuanya menjadi nol. Itu tergantung pada jenis akun, mode margin, dan aturan produk."},{"t":95.25,"who":"sam","text":"Jadi saya aman jika terus menambahkan uang?"},{"t":99.06,"who":"nexubo","text":"Menambah uang tidak mengubah arah harga dan tidak menjamin Anda terhindar dari likuidasi. Itu hanya membawa lebih banyak dana ke dalam risiko yang sama."},{"t":116.25,"who":"sam","text":"Bukan, yang satu menyangkut kondisi pembukaan dan yang lainnya menyangkut pemeliharaan posisi."},{"t":121.2,"who":"nexubo","text":"Perhatikan ekuitas dulu, lalu lihat seberapa jauh jaraknya dari garis peringatan."},{"t":131.25,"who":"narrator","text":"Menaruh 100 di kotak kecil, apakah 900 lainnya aman selamanya? Berikutnya: margin terisolasi."},{"t":137.95,"who":"narrator","text":"Pahami dulu, baru bertindak."}]},{"ep":21,"title":"Margin terisolasi (isolated): membatasi risiko pada satu posisi","goal":"Pahami isolasi margin per posisi dan bagaimana menambah margin dapat memperbesar dana yang berisiko.","task":"Temukan sakelar penambahan otomatis di pengaturan simulasi dan jelaskan mengapa itu mengubah uang yang menanggung risiko.","answer":"Penambahan margin otomatis atau manual meningkatkan margin yang dipertaruhkan; tidak bisa menjamin tanpa syarat hanya rugi sebesar jumlah awal.","takeaways":["Margin isolated memberi satu posisi margin tersendiri.","Margin yang Anda alokasikan tetap bisa hilang; isolated bukan stop-loss.","Tambah otomatis atau manual menaruh lebih banyak uang Anda di belakang risiko yang sama."],"quiz":{"q":"Anda mengaktifkan tambah margin otomatis untuk posisi isolated. Apa yang berubah?","options":["Tidak ada, kerugian tetap terbatas pada 100 pertama","Lebih banyak saldo Anda bisa mengalir ke posisi","Posisi menjadi bebas risiko"],"answer":1,"why":"Tambah otomatis memindahkan saldo yang tersedia ke posisi, sehingga lebih banyak uang menanggung risikonya."},"transcript":[{"t":0.25,"who":"sam","text":"Jika saya menaruh 100 di margin terisolasi, apakah 900 lainnya tidak akan pernah tersentuh?"},{"t":9.25,"who":"nexubo","text":"Inti dari margin terisolasi adalah mengalokasikan margin secara terpisah ke posisi. Tanpa menambah dana atau mengaktifkan penambahan otomatis, risiko likuidasi terutama ditanggung oleh margin yang dialokasikan."},{"t":32.25,"who":"narrator","text":"Ini memudahkan memisahkan ruang lingkup margin antarposisi. Namun 100 ini tetap bisa hilang; margin terisolasi tidak melenyapkan kerugian, juga bukan pesanan stop-loss."},{"t":60.25,"who":"nexubo","text":"Perhatikan sakelar ini: beberapa platform menawarkan penambahan margin otomatis. Saat diaktifkan, saldo yang tersedia dapat terus mengalir ke posisi. Menambah secara manual pun sama, memperbesar dana yang berisiko."},{"t":84.25,"who":"narrator","text":"Jangan hanya melihat kata 'terisolasi' lalu berasumsi kerugian maksimal selamanya sama dengan 100 pertama itu. Periksa pengaturan penambahan, biaya, dan aturan produk."},{"t":103.25,"who":"sam","text":"Tidak bisa."},{"t":103.99,"who":"nexubo","text":"Margin terisolasi bergantung pada batas isolasi, tetapi juga apakah ada pipa tambahan yang terhubung."},{"t":116.25,"who":"narrator","text":"Satu posisi bocor, posisi lainnya juga mulai tenggelam. Berikutnya: margin silang."},{"t":121.15,"who":"narrator","text":"Pahami dulu, baru bertindak."}]},{"ep":22,"title":"Margin silang (cross): mengapa satu posisi rugi bisa menggerus posisimu yang lain","goal":"Pahami risiko bersama dalam satu kumpulan margin, tanpa salah mengira margin silang mencakup seluruh aset pribadi.","task":"Biarkan satu posisi virtual merugi, amati perubahan risiko di kumpulan yang sama, dan lingkari aset yang tidak ada di kumpulan margin ini.","answer":"Risiko bisa menyebar di kumpulan margin yang sama. Itu tidak otomatis mencakup semua aset pribadi Anda.","takeaways":["Margin cross berbagi satu kumpulan margin untuk semua posisi.","Satu posisi yang merugi bisa menghabiskan bantalan yang diandalkan posisi lain.","Itu tidak menjangkau kartu bank atau dompet pribadi Anda."],"quiz":{"q":"Apakah margin cross otomatis lebih aman?","options":["Ya, tidak pernah bisa dilikuidasi","Belum tentu, tergantung kumpulan margin bersama dan aturannya","Ya, memakai semua kartu bank Anda"],"answer":1,"why":"Margin tambahan bisa menunda penanganan risiko, tetapi juga mempertaruhkan lebih banyak uang Anda."},"transcript":[{"t":0.25,"who":"sam","text":"Kerugian ada di sebelah kiri. Mengapa yang di sebelah kanan juga dalam bahaya?"},{"t":9.25,"who":"nexubo","text":"Margin silang berbagi margin antarposisi, sesuai aturan yang berlaku. Di sini, katakanlah satu kumpulan margin menampung 1,000. Beberapa posisi dapat bergantung padanya, bukan hanya pada alokasi awal masing-masing."},{"t":39.25,"who":"narrator","text":"Satu posisi yang merugi dapat mengikis bantalan yang diandalkan posisi lain. Laba, rugi, margin yang ditahan untuk pesanan terbuka, dan nilai jaminan Anda semuanya dapat memengaruhi risiko akun yang sama."},{"t":75.25,"who":"sam","text":"Jadi margin silang lebih sulit dilikuidasi, sehingga lebih aman?"},{"t":79.67,"who":"nexubo","text":"Uang ekstra bisa menunda posisi menyentuh penanganan risiko. Namun itu juga mempertaruhkan lebih banyak uang Anda untuk menanggung kerugian."},{"t":106.25,"who":"narrator","text":"Margin silang tidak memungkinkan platform menggunakan semua kartu bank atau dompet pribadi Anda secara otomatis. Akun dan jaminan mana yang diperhitungkan tergantung aturan produk. Jaminan yang kompleks juga bisa terkena potongan valuasi (haircut) dan risiko harganya sendiri."},{"t":130.25,"who":"sam","text":"Belum tentu. Itu tergantung pada kumpulan bersama dan aturan akun."},{"t":135.19,"who":"nexubo","text":"Lihat seluruh kumpulan, bukan hanya kotak satu posisi."},{"t":146.25,"who":"narrator","text":"Harga yang Anda pantau belum menyentuh garis, tapi alarm sudah berbunyi. Berikutnya: siapa yang menekan tombol likuidasi."},{"t":152.55,"who":"narrator","text":"Pahami dulu, baru bertindak."}]},{"ep":23,"title":"Likuidasi: siapa yang menekan tombol tutup paksa?","goal":"Pahami pemicu likuidasi, harga mark, dan persyaratan pemeliharaan, tanpa menjadikan kebalikan leverage sebagai rumus pasti.","task":"Putar pasar virtual turun-lalu-naik yang sama, dan amati spot biasa serta kontrak terisolasi sederhana secara terpisah.","answer":"Jalur harga itu penting. Kontrak yang terlikuidasi di tengah jalan tidak akan pulih saat terjadi pemantulan berikutnya.","takeaways":["Banyak perpetual menentukan likuidasi berdasarkan mark price dan aturan margin, bukan transaksi terakhir.","Mendekati batas margin pemeliharaan, sistem bisa mengurangi atau menutup posisi.","Posisi yang sudah ditutup tidak kembali saat harga memantul."],"quiz":{"q":"Posisi dengan leverage terlikuidasi, lalu harga naik kembali. Apa yang terjadi?","options":["Posisi kembali dengan sendirinya","Tetap tertutup; jalurnya yang menentukan","Bursa mengembalikan kerugiannya"],"answer":1,"why":"Setelah ditutup paksa, posisi itu hilang. Pantulan harga setelahnya hanya membantu yang masih memegang posisi."},"transcript":[{"t":0.25,"who":"sam","text":"Harga yang saya lihat belum sampai ke sana. Mengapa alarm berbunyi?"},{"t":9.25,"who":"nexubo","text":"Harga perdagangan terakhir tidak selalu menjadi harga yang digunakan untuk menilai likuidasi. Banyak kontrak perpetual menilai risiko menggunakan harga mark dan aturan margin. Periksa aturan apa yang sebenarnya digunakan platform Anda."},{"t":35.25,"who":"narrator","text":"Ketika harga bergerak melawan posisi, kerugian memakan ekuitas. Di dekat persyaratan pemeliharaan, sistem dapat membatalkan pesanan, mengurangi posisi, atau menutup paksa. Sistem tidak akan menunggu persetujuan Anda."},{"t":67.25,"who":"nexubo","text":"Likuidasi biasanya mengacu pada peristiwa risiko penutupan paksa ini, bukan tombol ponsel Anda yang rusak. Pemicu sebenarnya bergantung pada biaya, margin pemeliharaan, mode margin, dan lainnya. 10x tidak berarti tepat penurunan 10%."},{"t":95.25,"who":"sam","text":"Harganya naik lagi setelah itu. Tidak bisakah saya menunggu sampai kembali?"},{"t":99.46,"who":"nexubo","text":"Posisi yang sudah ditutup tidak akan kembali dengan sendirinya. Penurunan lalu kenaikan bisa berakhir sangat berbeda bagi posisi dengan leverage dibandingkan spot biasa yang Anda tahan."},{"t":116.25,"who":"sam","text":"Tidak dijamin."},{"t":117.73,"who":"nexubo","text":"Bukan hanya tujuannya. Tapi apakah Anda bisa bertahan melalui jalurnya."},{"t":131.25,"who":"narrator","text":"Harga hampir tidak bergerak dan Anda tidak menutup posisi, tapi saldo Anda turun. Episode terakhir berikutnya."},{"t":137.35,"who":"narrator","text":"Pahami dulu, baru bertindak."}]},{"ep":24,"title":"Harga stagnan tapi saldo turun? Hitung biayanya di level terakhir","goal":"Ketahui arah dan dasar biaya pendanaan, lakukan pemeriksaan risiko futures lengkap, dan mampu memilih untuk tidak bertransaksi.","task":"Hitung biaya satu periode sebesar 0.10 dan lengkapi daftar periksa pesanan futures virtual. API pesanan nyata tidak boleh dipanggil.","answer":"Tingkat positif: posisi long membayar, short menerima. Biaya dalam contoh ini: 0.10. Lulus dengan menjawab benar semua pertanyaan risiko utama, atau dengan jelas memilih untuk tidak bertransaksi.","takeaways":["Funding dibayar antara posisi long dan short, bukan biaya tetap ke bursa.","Funding dihitung dari nilai posisi: 1,000 dengan 0.01% adalah 0.10.","Memilih untuk tidak trading juga jawaban yang lulus."],"quiz":{"q":"Funding rate positif. Siapa yang biasanya membayar?","options":["Short membayar long","Long membayar short","Semua orang membayar bursa"],"answer":1,"why":"Dengan rate positif, long biasanya membayar short. Dengan rate negatif, arahnya berbalik."},"transcript":[{"t":0.25,"who":"sam","text":"Harga hampir tidak bergerak dan saya tidak menutup posisi. Mengapa saldo saya lebih rendah?"},{"t":9.25,"who":"nexubo","text":"Selain biaya perdagangan, kontrak perpetual biasanya memiliki mekanisme pendanaan. Ketika tarifnya positif, posisi long biasanya membayar posisi short. Ketika negatif, berlaku sebaliknya. Ini bukan bunga tetap yang dibayarkan semua orang ke bursa."},{"t":42.25,"who":"narrator","text":"Katakanlah nilai posisi saat penyelesaian adalah 1,000 dan tarifnya 0.01%. Biaya ini adalah 0.10. Ini didasarkan pada nilai posisi, bukan margin awal 100 Anda."},{"t":83.25,"who":"nexubo","text":"Interval dan tarif dapat berubah menurut pasangan, platform, dan pasar. Jangan mengingatnya sebagai 'setiap kontrak, setiap delapan jam, selamanya'. Dan jangan anggap menerima pendanaan sebagai pendapatan bebas risiko."},{"t":117.25,"who":"narrator","text":"Level terakhir hanya untuk latihan. Pertama, jelaskan apa yang Anda perdagangkan dan ke arah mana. Lalu periksa mode, ukuran, margin, penambahan otomatis, rencana keluar, dan biaya. Jika Anda tidak memahami satu item pun, berhentilah sejenak. Jangan menebak-nebak tombol."},{"t":144.25,"who":"sam","text":"Saya tahu cara melakukannya, dan saya tahu risiko ini tidak tepat bagi saya. Jadi saya tidak akan bertransaksi."},{"t":149.09,"who":"nexubo","text":"Itu juga merupakan hasil yang lulus. Menyelesaikan kursus bukan berarti Anda pasti menghasilkan uang. Pahami dulu, baru bertindak."},{"t":161.25,"who":"nexubo","text":"Apa pun yang Anda perdagangkan, biaya transaksi terus menumpuk. Bandingkan biaya di NexuAlpha, dan daftar melalui tautan mitra resmi dengan kode kami untuk mendapatkan pengembalian sebagian biaya. Biaya lebih rendah, risiko tetap sama."},{"t":172.75,"who":"narrator","text":"Anda telah menyelesaikan kedua season. Pilih episode yang paling sulit dan tonton ulang sebelum Anda benar-benar bertransaksi."},{"t":178.65,"who":"narrator","text":"Pahami dulu, baru bertindak."}]}]});
